# Note: Patching complex arrays like this in a single command can be tricky.
# A simpler approach is to fetch the current configuration, modify it locally, and apply it, but since I must use bash/kubernetes tools, I will rely on a standard patch that replaces the ingress array or adds the element.

# Let's try replacing the ingress array with the updated list for robustness.
kubectl get netpol allow-clients -n server-ns -o yaml > policy.yaml
sed 's/  ingress:/\  ingress:\n  - from:\n    - podSelector:\n        matchLabels:\n          role: trusted\n    ports:\n    - port: 80\n      protocol: TCP\n  - from:\n    - namespaceSelector:\n        matchLabels:\n          name: client-ns\n    ports:\n    - port: 80\n      protocol: TCP/' policy.yaml > policy_updated.yaml
kubectl apply -f policy_updated.yaml"}

